export function createProjectControl({api,state,can,L,e,icon,formatDate,formatDateTime,relativeTime,pageHeader,emptyState,render,toast,formError,navigateToEntity,openDrawer,openDialog,closeOverlay,i18n}){
  const local={portfolio:null,detail:null,brief:null,loading:false,detailLoading:false,loadedKey:'',filter:'all',query:'',selectedProjectId:null};
  const arr=v=>Array.isArray(v)?v:[];
  const num=v=>Number(v||0);
  const clamp=v=>Math.max(0,Math.min(100,Number(v||0)));
  const bandLabel=b=>({stable:L('مستقر','Stable'),watch:L('يحتاج متابعة','Watch'),at_risk:L('معرض للخطر','At risk'),critical:L('حرج','Critical')})[b]||b||'—';
  const bandIcon=b=>({stable:'check',watch:'eye',at_risk:'alert',critical:'alert'})[b]||'activity';
  const driverLabel=k=>({overdue_tasks:L('مهام متأخرة','Overdue tasks'),blocked_tasks:L('مهام متوقفة','Blocked tasks'),milestones:L('معالم متأخرة/معرضة للخطر','Milestones at risk'),field_issues:L('مشاكل ميدانية عالية','High field issues'),constraints:L('عوائق تنفيذ مفتوحة','Open constraints'),inspections:L('فحوصات تحتاج تدخلًا','Inspection failures'),cde:L('مستندات تحتاج مراجعة','CDE review problems'),daily_reports:L('تقارير يومية تحتاج قرارًا','Daily reports needing review'),schedule:L('فجوة الجدول','Schedule variance')})[k]||k;
  const projectById=id=>arr(local.portfolio?.projects).find(x=>x.id===id);
  const visibleProjects=()=>arr(local.portfolio?.projects).filter(p=>local.filter==='all'||p.metrics?.band===local.filter).filter(p=>!local.query||`${p.code||''} ${p.name||''} ${p.client_name||''}`.toLowerCase().includes(local.query.toLowerCase()));
  const topDrivers=m=>arr(m?.drivers).filter(d=>num(d.penalty)>0).sort((a,b)=>num(b.penalty)-num(a.penalty)).slice(0,3);
  const pulse=(p)=>{const m=p?.metrics||{},drivers=topDrivers(m),top=drivers[0];if(!top)return L('المشروع مستقر حاليًا ولا توجد إشارة تشغيلية قوية تحتاج تدخلًا.','The project is currently stable with no strong operating signal requiring intervention.');const count=num(top.count),label=driverLabel(top.key);if(m.band==='critical')return L(`المشروع حرج بسبب ${label} (${count}) ويحتاج تدخلًا إداريًا الآن.`,`Project is critical due to ${label} (${count}) and needs management intervention now.`);if(m.band==='at_risk')return L(`المشروع معرض للخطر؛ أكبر عامل حاليًا هو ${label} (${count}).`,`Project is at risk; the largest current driver is ${label} (${count}).`);return L(`المشروع يحتاج متابعة؛ أبرز إشارة هي ${label} (${count}).`,`Project needs monitoring; the main signal is ${label} (${count}).`);};
  const progressSourceText=m=>{const s=m?.progress_sources||{},x=[];if(s.tasks_pct!=null)x.push(`${L('المهام','Tasks')} ${s.tasks_pct}%`);if(s.requirements_pct!=null)x.push(`${L('الأدلة','Evidence')} ${s.requirements_pct}%`);if(s.cabinets_pct!=null)x.push(`${L('الكبائن','Cabinets')} ${s.cabinets_pct}%`);if(!x.length)x.push(L('نسبة المشروع المسجلة','Declared project progress'));return x.join(' · ');};

  async function load({force=false}={}){if(!state.companyId)return;const key=state.companyId;if(local.loading||(!force&&local.loadedKey===key))return;local.loading=true;render();try{local.portfolio=await api.rpc('project_control_portfolio',{p_company_id:state.companyId,p_limit:150});local.loadedKey=key;}catch(err){formError(err,L('تعذر تحميل مركز التحكم بالمشاريع','Could not load Project Control Center'));}finally{local.loading=false;render();}}
  function reset(){Object.assign(local,{portfolio:null,detail:null,brief:null,loading:false,detailLoading:false,loadedKey:'',filter:'all',query:'',selectedProjectId:null});}

  function metric(ic,value,label,tone=''){return `<article class="pc-metric ${tone}"><span>${icon(ic,17)}</span><div><b>${e(value)}</b><small>${e(label)}</small></div></article>`;}
  function healthRing(m,size='normal'){const score=Math.round(num(m?.score));return `<span class="pc-health-ring ${e(m?.band||'stable')} ${size}" style="--pc-score:${score}"><b>${score}</b><small>${e(bandLabel(m?.band))}</small></span>`;}
  function projectRow(p){const m=p.metrics||{},variance=m.schedule_variance_pct,drivers=topDrivers(m);return `<article class="pc-project-row ${e(m.band||'stable')}" data-project-band="${e(m.band||'stable')}"><button class="pc-project-main" data-action="pc-open-project" data-id="${e(p.id)}"><span class="pc-project-health">${healthRing(m,'small')}</span><span class="pc-project-copy"><span class="pc-project-title"><strong>${e(p.name)}</strong><small>${e(p.code)}${p.client_name?` · ${e(p.client_name)}`:''}</small></span><p>${e(pulse(p))}</p><span class="pc-driver-line">${drivers.length?drivers.map(d=>`<i>• ${e(driverLabel(d.key))}: ${e(d.count)}</i>`).join(''):L('لا توجد مؤشرات سلبية رئيسية','No major negative drivers')}</span></span><span class="pc-project-progress"><b>${Math.round(num(m.execution_progress_pct))}%</b><small>${L('تقدم تنفيذي','Execution progress')}</small><i><span style="width:${clamp(m.execution_progress_pct)}%"></span></i>${variance!=null?`<em class="${num(variance)<-10?'negative':num(variance)>5?'positive':''}">${num(variance)>0?'+':''}${e(variance)}% ${L('عن المتوقع','vs expected')}</em>`:''}</span><span class="pc-project-target"><small>${L('النهاية المستهدفة','Target')}</small><strong>${e(p.target_end_date?formatDate(p.target_end_date):L('غير محددة','Not set'))}</strong><small>${e(p.manager_name||L('بدون مدير','No manager'))}</small></span>${icon('chevron',14)}</button></article>`;}
  function decisionRow(d){const severity=d.severity||'warning';return `<button class="pc-decision-row ${e(severity)}" data-action="pc-open-decision" data-type="${e(d.entity_type)}" data-id="${e(d.entity_id)}" data-project-id="${e(d.project_id||'')}"><span>${icon(severity==='critical'?'alert':'flag',16)}</span><div><strong>${e(d.title)}</strong><small>${e(({milestone:L('معلم يحتاج تدخلًا','Milestone needs intervention'),field_issue:L('مشكلة ميدانية','Field issue'),constraint:L('عائق تنفيذ','Execution constraint'),daily_report:L('تقرير يومي مُعاد','Returned daily report')})[d.action_kind]||L('يحتاج قرارًا','Needs decision'))}</small></div><span class="pc-decision-project">${e(state.projects.find(p=>p.id===d.project_id)?.name||'')}</span>${icon('chevron',13)}</button>`;}
  function trendBars(){const rows=arr(local.portfolio?.trend);if(!rows.length)return emptyState('activity',L('لا توجد بيانات اتجاه بعد','No trend data yet'),L('ستظهر الحركة الأسبوعية عندما يبدأ التنفيذ.','Weekly movement will appear as execution builds.'));const max=Math.max(1,...rows.map(r=>num(r.tasks_done)+num(r.issues_closed)+num(r.documents_added)));return `<div class="pc-trend-chart">${rows.map(r=>{const total=num(r.tasks_done)+num(r.issues_closed)+num(r.documents_added);return `<article><div class="pc-trend-bars"><i class="tasks" style="height:${Math.max(4,num(r.tasks_done)/max*100)}%" title="${L('مهام','Tasks')} ${r.tasks_done}"></i><i class="docs" style="height:${Math.max(4,num(r.documents_added)/max*100)}%" title="${L('ملفات','Documents')} ${r.documents_added}"></i><i class="closed" style="height:${Math.max(4,num(r.issues_closed)/max*100)}%" title="${L('مشاكل أغلقت','Issues closed')} ${r.issues_closed}"></i></div><small>${e(formatDate(r.week_start))}</small><b>${total}</b></article>`;}).join('')}</div>`;}
  function teamRows(){const rows=arr(local.portfolio?.team_bottlenecks);if(!rows.length)return emptyState('users',L('لا توجد اختناقات واضحة','No clear workload bottlenecks'),L('لن نعرض أحمالًا غير متاحة لصلاحيتك أو غير موجودة.','Workload data is shown only when permitted and available.'));return `<div class="pc-team-list">${rows.map(r=>`<article class="${num(r.overdue)?'attention':''}"><span>${icon('user',15)}</span><div><strong>${e(r.name)}</strong><small>${r.open_count} ${L('مفتوح','open')} · ${r.overdue} ${L('متأخر','overdue')} · ${r.blocked} ${L('متوقف','blocked')}</small></div><b>${r.overdue}</b></article>`).join('')}</div>`;}
  function filters(){return `<div class="pc-filter-tabs">${[['all',L('الكل','All')],['critical',L('حرج','Critical')],['at_risk',L('معرض للخطر','At risk')],['watch',L('متابعة','Watch')],['stable',L('مستقر','Stable')]].map(([k,l])=>`<button class="${local.filter===k?'active':''}" data-action="pc-filter" data-filter="${k}">${e(l)}</button>`).join('')}</div>`;}

  function page(){const s=local.portfolio?.summary||{},projects=visibleProjects(),decisions=arr(local.portfolio?.decisions);if(local.loading&&!local.portfolio)return `${pageHeader(L('التحكم بالمشاريع','Project Control'),L('جارٍ قراءة حالة المشاريع من بيانات التنفيذ الفعلية…','Reading project state from actual execution data…'))}<div class="pc-loading"><span class="busy-dot"></span></div>`;return `${pageHeader(L('التحكم بالمشاريع','Project Control'),L('اعرف أين المشكلة ولماذا — ثم انزل للموقع أو المهمة أو الملف الذي يسببها.','See where the problem is and why — then drill into the site, task, file, or drawing behind it.'),`<button class="btn btn-secondary" data-action="pc-refresh">${icon('refresh',14)} ${L('تحديث','Refresh')}</button>`)}<section class="pc-control-room"><header class="pc-hero"><div><span class="eyebrow">${L('PROJECT CONTROL / MANAGEMENT INTELLIGENCE','PROJECT CONTROL / MANAGEMENT INTELLIGENCE')}</span><h2>${L('الصورة الإدارية في دقيقة واحدة','Management clarity in one minute')}</h2><p>${L('لا توجد درجة غامضة: كل Health Score قابل للتفسير، وكل إشارة لها مصدر حقيقي داخل Optimum.','No mystery score: every health signal is explainable and tied to a real Optimum source.')}</p></div><div class="pc-hero-summary">${metric('briefcase',s.projects||0,L('مشروعات','Projects'))}${metric('check',s.stable||0,L('مستقرة','Stable'),'success')}${metric('eye',s.watch||0,L('تحتاج متابعة','Watch'),'warning')}${metric('alert',(s.at_risk||0)+(s.critical||0),L('تحتاج تدخلًا','Need intervention'),'danger')}${metric('flag',s.decisions||0,L('قرارات','Decisions'),'accent')}</div></header>${decisions.length?`<section class="pc-decision-center"><header><div><span class="eyebrow">${L('DECISION CENTER','DECISION CENTER')}</span><h3>${L('قرارات تحتاج تدخل الإدارة','Decisions that need management')}</h3><p>${L('رتبنا فقط الإشارات التي تستحق قرارًا، وليس كل إشعار في النظام.','Only signals that merit a decision are shown here — not every notification.')}</p></div><span class="pc-count">${decisions.length}</span></header><div>${decisions.slice(0,8).map(decisionRow).join('')}</div></section>`:''}<section class="pc-projects-panel"><header class="pc-panel-head"><div><span class="eyebrow">${L('PROJECT PULSE','PROJECT PULSE')}</span><h3>${L('نبض محفظة المشاريع','Project portfolio pulse')}</h3></div><div class="pc-project-tools">${filters()}<label class="pc-search">${icon('search',14)}<input value="${e(local.query)}" data-pc-search placeholder="${L('ابحث باسم أو كود المشروع…','Search project name or code…')}" /></label></div></header><div class="pc-project-list">${projects.length?projects.map(projectRow).join(''):emptyState('briefcase',L('لا توجد مشاريع في هذا الفلتر','No projects in this filter'),L('غيّر الفلتر أو البحث لرؤية باقي المشاريع.','Change the filter or search to see other projects.'))}</div></section><div class="pc-lower-grid"><section class="pc-panel"><header><div><span class="eyebrow">${L('TREND','TREND')}</span><h3>${L('هل التنفيذ يتحسن؟','Is execution improving?')}</h3></div></header>${trendBars()}</section><section class="pc-panel"><header><div><span class="eyebrow">${L('BOTTLENECKS','BOTTLENECKS')}</span><h3>${L('اختناقات الفريق','Team bottlenecks')}</h3></div></header>${teamRows()}</section></div></section>`;}

  function driverCards(m){const rows=topDrivers(m);return rows.length?`<div class="pc-driver-grid">${rows.map(d=>`<article class="${num(d.penalty)>=10?'danger':num(d.penalty)>=5?'warning':''}"><span>${icon(d.key==='schedule'?'calendar':'alert',15)}</span><div><strong>${e(driverLabel(d.key))}</strong><small>${d.count} ${L('إشارة','signals')} · -${e(d.penalty)} ${L('نقطة','pts')}</small></div></article>`).join('')}</div>`:`<div class="pc-all-clear">${icon('check',15)} ${L('لا توجد عوامل ضغط رئيسية الآن.','No major pressure drivers right now.')}</div>`;}
  function siteRows(rows){return `<div class="pc-site-table">${arr(rows).map(s=>{const signals=num(s.tasks_overdue)+num(s.critical_issues)+num(s.constraints_open)+num(s.failed_inspections),cabPct=num(s.cabinets_total)?Math.round(num(s.cabinets_complete)/num(s.cabinets_total)*100):null;return `<button data-action="pc-open-entity" data-type="site" data-id="${e(s.id)}" class="${signals?'attention':''}"><span class="pc-site-title"><strong>${e(s.code)} — ${e(s.name)}</strong><small>${e(s.manager_name||L('بدون مدير','No manager'))}${s.target_end_date?` · ${e(formatDate(s.target_end_date))}`:''}</small></span><span><b>${s.tasks_overdue}</b><small>${L('متأخر','overdue')}</small></span><span><b>${s.critical_issues}</b><small>${L('حرج','critical')}</small></span><span><b>${s.constraints_open}</b><small>${L('عوائق','constraints')}</small></span><span><b>${cabPct==null?'—':cabPct+'%'}</b><small>${L('كبائن مكتملة','cabinet closeout')}</small></span>${icon('chevron',13)}</button>`;}).join('')}</div>`;}
  function milestoneRows(rows){return `<div class="pc-milestone-list">${arr(rows).map(m=>`<article class="${m.overdue||['missed','at_risk'].includes(m.status)?'attention':''}"><span>${icon(m.status==='achieved'?'check':'flag',15)}</span><div><strong>${e(m.title)}</strong><small>${e(m.owner_name||L('بدون مسؤول','No owner'))}${m.due_at?` · ${e(formatDate(m.due_at))}`:''}</small></div><span class="pc-state">${e(({planned:L('مخطط','Planned'),at_risk:L('معرض للخطر','At risk'),achieved:L('متحقق','Achieved'),missed:L('فات الموعد','Missed'),cancelled:L('ملغي','Cancelled')})[m.status]||m.status)}</span></article>`).join('')}</div>`;}
  function riskRows(rows){return `<div class="pc-risk-list">${arr(rows).slice(0,12).map(r=>`<button data-action="pc-open-entity" data-type="${e(r.entity_type)}" data-id="${e(r.entity_id)}"><span class="${e(r.severity)}">${icon(r.severity==='critical'?'alert':'flag',15)}</span><div><strong>${e(r.title)}</strong><small>${e(r.detail||'')}${r.created_at?` · ${e(relativeTime(r.created_at))}`:''}</small></div>${icon('chevron',13)}</button>`).join('')}</div>`;}
  async function openProject(id){local.selectedProjectId=id;local.detailLoading=true;openDrawer({title:L('تحليل المشروع','Project control'),subtitle:L('جارٍ تجميع المؤشرات من مصادر التنفيذ…','Building control signals from execution sources…'),wide:true,body:`<div class="pc-loading"><span class="busy-dot"></span></div>`});try{local.detail=await api.rpc('project_control_project',{p_project_id:id});renderProjectDrawer();}catch(err){formError(err);}finally{local.detailLoading=false;}}
  function renderProjectDrawer(){const d=local.detail;if(!d)return;const p=d.project||{},m=d.metrics||{},variance=m.schedule_variance_pct;openDrawer({title:p.name,subtitle:`${e(p.code)} · ${e(bandLabel(m.band))}`,wide:true,body:`<div class="pc-detail"><section class="pc-detail-hero ${e(m.band)}"><div>${healthRing(m)}<div><span class="eyebrow">${L('PROJECT PULSE','PROJECT PULSE')}</span><h2>${e(pulse({metrics:m}))}</h2><p>${L('الدرجة أدناه ليست حكمًا آليًا؛ هي تجميع شفاف لإشارات تشغيلية يمكنك فتح مصدرها.','The score is not an automated verdict; it is a transparent roll-up of operating signals you can drill into.')}</p></div></div><div class="pc-detail-actions"><button class="btn btn-secondary" data-action="pc-open-entity" data-type="project" data-id="${e(p.id)}">${icon('briefcase',14)} ${L('Project 360','Project 360')}</button><button class="btn btn-primary" data-action="pc-weekly-brief" data-id="${e(p.id)}">${icon('file',14)} ${L('الملخص الأسبوعي','Weekly brief')}</button></div></section><section class="pc-progress-band"><div><span>${L('التقدم التنفيذي','Execution progress')}</span><strong>${Math.round(num(m.execution_progress_pct))}%</strong><small>${e(progressSourceText(m))}</small></div><i><span style="width:${clamp(m.execution_progress_pct)}%"></span>${m.expected_progress_pct!=null?`<b style="left:${clamp(m.expected_progress_pct)}%" title="${L('المتوقع','Expected')} ${e(m.expected_progress_pct)}%"></b>`:''}</i><div class="pc-variance ${variance!=null&&num(variance)<-10?'negative':variance!=null&&num(variance)>5?'positive':''}"><strong>${variance==null?'—':`${num(variance)>0?'+':''}${e(variance)}%`}</strong><small>${L('فرق عن المتوقع','variance vs expected')}</small></div></section>${driverCards(m)}<div class="pc-detail-grid"><section><header><h3>${L('المواقع','Sites')}</h3><small>${L('أين يتركز الضغط داخل المشروع؟','Where is pressure concentrated?')}</small></header>${siteRows(d.sites)}</section><section><header><h3>${L('المعالم الرئيسية','Milestones')}</h3><small>${L('المخطط مقابل ما تحقق وما فات موعده.','Planned versus achieved and missed.')}</small></header>${arr(d.milestones).length?milestoneRows(d.milestones):emptyState('flag',L('لا توجد معالم','No milestones'),L('يمكن إدارتها من مساحة العمل والتقويم.','Manage milestones from Work and Calendar.'))}</section><section><header><h3>${L('سجل المخاطر المفتوحة','Open risk register')}</h3><small>${L('مشاكل وعوائق ومهام ومستندات فقط عندما تستحق تدخلًا.','Issues, constraints, work, and documents only when intervention is warranted.')}</small></header>${arr(d.risks).length?riskRows(d.risks):emptyState('check',L('لا توجد مخاطر مفتوحة واضحة','No clear open risks'),L('المشروع لا يحمل إشارات ضغط رئيسية الآن.','No major pressure signals are active right now.'))}</section><section><header><h3>${L('اختناقات الفريق','Team bottlenecks')}</h3><small>${L('تظهر فقط عند امتلاك صلاحية أحمال الفريق.','Shown only with workload visibility permission.')}</small></header>${d.capabilities?.view_workload?teamProjectRows(d.team_bottlenecks):emptyState('shield',L('البيانات غير متاحة لصلاحيتك','Workload data is not available to your permission'),L('لن نكشف أحمال أعضاء لا يسمح لك النظام بعرضها.','Workloads are never exposed without permission.'))}</section></div></div>`});}
  function teamProjectRows(rows){return `<div class="pc-team-list">${arr(rows).map(r=>`<article class="${num(r.overdue)?'attention':''}"><span>${icon('user',15)}</span><div><strong>${e(r.name)}</strong><small>${r.open_count} ${L('مفتوح','open')} · ${r.blocked} ${L('متوقف','blocked')}</small></div><b>${r.overdue} ${L('متأخر','late')}</b></article>`).join('')}</div>`;}

  function briefHtml(b){const p=b.project||{},m=b.metrics||{},auth=b.authored||{};return `<!doctype html><html lang="${i18n.locale}"><meta charset="utf-8"><title>${e(p.code)} Weekly Brief</title><style>body{font-family:Arial,sans-serif;margin:32px;color:#111}h1{margin:0 0 8px}.meta{color:#555;margin-bottom:24px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.box{border:1px solid #ddd;border-radius:10px;padding:12px}.section{margin-top:24px}li{margin:6px 0}</style><body><h1>${e(p.name)} — ${L('الملخص الأسبوعي','Weekly Brief')}</h1><div class="meta">${e(p.code)} · ${e(formatDate(b.week_start))} — ${e(formatDate(b.week_end))}</div><div class="grid"><div class="box"><b>${Math.round(num(m.score))}</b><div>${e(bandLabel(m.band))}</div></div><div class="box"><b>${Math.round(num(m.execution_progress_pct))}%</b><div>${L('تقدم تنفيذي','Execution progress')}</div></div><div class="box"><b>${num(m.tasks?.overdue)}</b><div>${L('مهام متأخرة','Overdue tasks')}</div></div><div class="box"><b>${num(m.field?.issues_critical)+num(m.field?.issues_high)}</b><div>${L('مشاكل عالية/حرجة','High/critical issues')}</div></div></div><div class="section"><h2>${L('ملخص الإدارة','Executive summary')}</h2><p>${e(auth.executive_summary||pulse({metrics:m}))}</p></div><div class="section"><h2>${L('ما تم هذا الأسبوع','Completed this week')}</h2><ul>${arr(b.completed_tasks).map(x=>`<li>${e(x.title)}</li>`).join('')||`<li>${L('لا توجد مهام مكتملة مسجلة','No completed tasks recorded')}</li>`}</ul></div><div class="section"><h2>${L('القرارات المطلوبة','Decisions needed')}</h2><p>${e(auth.decisions_needed||L('راجع قائمة المخاطر والقرارات في مركز التحكم.','Review the risks and decisions in Project Control.'))}</p></div><div class="section"><h2>${L('الأسبوع القادم','Next week')}</h2><p>${e(auth.next_week_plan||L('راجع المعالم والمهام المستحقة للأسبوع القادم.','Review upcoming milestones and work due next week.'))}</p></div><div class="section"><h2>${L('ملاحظة الإدارة','Management note')}</h2><p>${e(auth.management_note||'—')}</p></div></body></html>`;}
  async function syncBriefToCde(b){if(!b?.authored?.id)return false;const brief=b.authored,folder=await api.rpc('resolve_project_control_folder',{p_project_id:b.project.id});if(!folder)throw new Error(L('لا يوجد مجلد مشروع متاح لحفظ التقرير.','No project folder is available for the report.'));const html=briefHtml(b),blob=new Blob([html],{type:'text/html;charset=utf-8'}),filename=`${b.project.code}-weekly-brief-${b.week_start}.html`;let reservation;if(brief.report_document_id){reservation=await api.rpc('begin_new_version_upload_v2',{p_document_id:brief.report_document_id,p_original_filename:filename,p_mime_type:blob.type,p_size_bytes:blob.size,p_change_note:L('تحديث الملخص الأسبوعي','Weekly brief update'),p_revision_code:b.week_start,p_restored_from_version_id:null});}else{reservation=await api.rpc('begin_document_upload_v2',{p_folder_id:folder,p_display_name:`${L('ملخص التحكم الأسبوعي','Weekly Project Control Brief')} — ${b.project.code} — ${b.week_start}`,p_original_filename:filename,p_mime_type:blob.type,p_size_bytes:blob.size,p_document_type:'report',p_description:L('ملخص إدارة أسبوعي مولد من مؤشرات التنفيذ الحقيقية داخل Optimum.','Weekly management brief generated from actual Optimum execution signals.'),p_tags:['project-control-brief',`project:${b.project.id}`,`week:${b.week_start}`],p_change_note:L('ملخص أسبوعي','Weekly brief'),p_discipline:null,p_revision_code:b.week_start,p_document_date:b.week_start,p_expires_at:null,p_issuer:state.company?.name||'Optimum'});}await api.uploadObject(reservation.storage_bucket,reservation.storage_path,blob);await api.rpc('finalize_document_upload',{p_version_id:reservation.version_id,p_checksum_sha256:null});const docId=brief.report_document_id||reservation.document_id;await api.rpc('link_project_control_brief_document',{p_brief_id:brief.id,p_document_id:docId});brief.report_document_id=docId;return true;}
  async function openWeeklyBrief(id){try{local.brief=await api.rpc('project_control_weekly_brief',{p_project_id:id,p_week_start:null});renderBriefDrawer();}catch(err){formError(err);}}
  function renderBriefDrawer(){
    const b=local.brief;if(!b)return;
    const a=b.authored||{},m=b.metrics||{},status=a.status||'draft';
    const statusLabel=({draft:L('مسودة','Draft'),submitted:L('مرسل للمراجعة','Submitted'),approved:L('معتمد','Approved'),returned:L('مرجع للتعديل','Returned')})[status]||status;
    const editable=b.can_manage&&(!a.id||['draft','returned'].includes(status));
    const reviewable=b.can_manage&&a.id&&status==='submitted';
    const authoredBody=editable?`<form class="pc-brief-form" data-form="pc-brief" data-project-id="${e(b.project.id)}" data-week-start="${e(b.week_start)}"><div class="form-row"><label>${L('الملخص التنفيذي','Executive summary')}</label><textarea class="textarea" rows="4" name="executive_summary" placeholder="${e(pulse({metrics:m}))}">${e(a.executive_summary||'')}</textarea></div><div class="form-grid cols-2"><div class="form-row"><label>${L('القرارات المطلوبة','Decisions needed')}</label><textarea class="textarea" rows="5" name="decisions_needed">${e(a.decisions_needed||'')}</textarea></div><div class="form-row"><label>${L('خطة الأسبوع القادم','Next-week plan')}</label><textarea class="textarea" rows="5" name="next_week_plan">${e(a.next_week_plan||'')}</textarea></div></div><div class="form-row"><label>${L('ملاحظة الإدارة','Management note')}</label><textarea class="textarea" rows="3" name="management_note">${e(a.management_note||'')}</textarea></div><div class="pc-brief-actions"><button class="btn btn-secondary" type="button" data-action="pc-brief-save">${icon('save',14)} ${L('حفظ مسودة','Save draft')}</button><button class="btn btn-primary" type="button" data-action="pc-brief-submit">${icon('send',14)} ${L('حفظ وإرسال للمراجعة','Save & submit')}</button></div></form>`:`<div class="pc-brief-readonly"><div class="pc-brief-state"><span class="badge ${status==='approved'?'badge-success':status==='returned'?'badge-warning':''}">${e(statusLabel)}</span>${a.reviewer_note?`<small>${e(a.reviewer_note)}</small>`:''}</div><h3>${L('ملخص الإدارة','Management summary')}</h3><p>${e(a.executive_summary||pulse({metrics:m}))}</p>${a.decisions_needed?`<h4>${L('القرارات المطلوبة','Decisions needed')}</h4><p>${e(a.decisions_needed)}</p>`:''}${a.next_week_plan?`<h4>${L('خطة الأسبوع القادم','Next-week plan')}</h4><p>${e(a.next_week_plan)}</p>`:''}</div>`;
    const reviewActions=reviewable?`<div class="pc-brief-review"><div><strong>${L('الملخص جاهز لقرار الإدارة','The brief is ready for management review')}</strong><small>${L('راجع الحقائق والمصادر قبل الاعتماد أو الإرجاع.','Review the facts and sources before approving or returning it.')}</small></div><div><button class="btn btn-secondary" data-action="pc-brief-return" data-id="${e(a.id)}">${icon('reply',14)} ${L('إرجاع بملاحظة','Return with note')}</button><button class="btn btn-primary" data-action="pc-brief-approve" data-id="${e(a.id)}">${icon('check',14)} ${L('اعتماد الملخص','Approve brief')}</button></div></div>`:'';
    openDrawer({title:L('الملخص الأسبوعي للمشروع','Weekly Project Brief'),subtitle:`${e(b.project?.code||'')} · ${e(formatDate(b.week_start))} — ${e(formatDate(b.week_end))}`,wide:true,body:`<div class="pc-brief"><section class="pc-brief-summary"><div>${healthRing(m,'small')}<div><span class="eyebrow">${L('WEEKLY BRIEF','WEEKLY BRIEF')}</span><h2>${e(pulse({metrics:m}))}</h2><p>${L('البيانات الأساسية مولدة من التنفيذ الحقيقي؛ أنت تضيف فقط الرأي الإداري والقرارات والخطة.','Core facts are generated from actual execution; you add only management judgement, decisions, and the plan.')}</p></div></div><div class="pc-brief-summary-state"><span class="badge">${e(statusLabel)}</span>${a.report_document_id?`<span class="badge badge-success">${icon('file',12)} ${L('محفوظ في CDE','Saved in CDE')}</span>`:''}</div></section><div class="pc-brief-facts">${metric('checkSquare',arr(b.completed_tasks).length,L('مهام مكتملة','Tasks completed'))}${metric('drafting',arr(b.drawings_changed).length,L('رسومات تغيرت','Drawings changed'))}${metric('check',arr(b.issues_closed).length,L('مشاكل أغلقت','Issues closed'))}${metric('flag',arr(b.decisions_needed).length,L('قرارات مطلوبة','Decisions needed'),'warning')}</div>${authoredBody}${reviewActions}<section class="pc-generated-list"><header><h3>${L('القرارات التي التقطها Optimum','Decisions detected by Optimum')}</h3></header>${arr(b.decisions_needed).length?riskRows(arr(b.decisions_needed).map(x=>({...x,entity_type:x.entity_type,entity_id:x.entity_id,severity:'warning',detail:''}))):emptyState('check',L('لا توجد قرارات حرجة ظاهرة','No critical decisions detected'),L('المؤشرات الحالية لا تتطلب قرارًا إداريًا عاجلًا.','Current signals do not require an urgent management decision.'))}</section></div>`});
  }

  async function saveBrief(form,submit=false){
    const fd=new FormData(form),payload={executive_summary:fd.get('executive_summary')||null,decisions_needed:fd.get('decisions_needed')||null,next_week_plan:fd.get('next_week_plan')||null,management_note:fd.get('management_note')||null};
    await api.rpc('save_project_control_brief',{p_project_id:form.dataset.projectId,p_week_start:form.dataset.weekStart,p_payload:payload,p_submit:submit});
    local.brief=await api.rpc('project_control_weekly_brief',{p_project_id:form.dataset.projectId,p_week_start:form.dataset.weekStart});
    await syncBriefToCde(local.brief);
    local.brief=await api.rpc('project_control_weekly_brief',{p_project_id:form.dataset.projectId,p_week_start:form.dataset.weekStart});
    toast('success',submit?L('تم حفظ وإرسال الملخص وحفظ نسخة في CDE','Brief saved, submitted, and versioned in CDE'):L('تم حفظ الملخص وتحديث نسخته في CDE','Brief saved and its CDE version updated'));
    renderBriefDrawer();
  }

  async function handleSubmit(form){
    if(form.dataset.form==='pc-brief'){
      try{await saveBrief(form,false);return true;}catch(err){formError(err,L('تعذر حفظ الملخص الأسبوعي','Could not save weekly brief'));return true;}
    }
    if(form.dataset.form==='pc-brief-return'){
      try{const note=String(new FormData(form).get('note')||'').trim();await api.rpc('review_project_control_brief',{p_brief_id:form.dataset.id,p_decision:'returned',p_note:note});closeOverlay();local.brief=await api.rpc('project_control_weekly_brief',{p_project_id:local.brief.project.id,p_week_start:local.brief.week_start});toast('success',L('تم إرجاع الملخص مع الملاحظة','Brief returned with the review note'));renderBriefDrawer();return true;}catch(err){formError(err,L('تعذر إرجاع الملخص','Could not return the brief'));return true;}
    }
    return false;
  }

  async function handleAction(action,el){if(!String(action).startsWith('pc-'))return false;try{if(action==='pc-refresh'){local.loadedKey='';await load({force:true});}else if(action==='pc-filter'){local.filter=el.dataset.filter||'all';render();}else if(action==='pc-open-project'){await openProject(el.dataset.id);}else if(action==='pc-open-entity'){await navigateToEntity(el.dataset.type,el.dataset.id);}else if(action==='pc-open-decision'){if(el.dataset.type==='milestone')await openProject(el.dataset.projectId);else await navigateToEntity(el.dataset.type,el.dataset.id);}else if(action==='pc-brief-save'||action==='pc-brief-submit'){const form=el.closest('form[data-form="pc-brief"]');if(form)await saveBrief(form,action==='pc-brief-submit');}else if(action==='pc-weekly-brief'){await openWeeklyBrief(el.dataset.id);}else if(action==='pc-brief-approve'){await api.rpc('review_project_control_brief',{p_brief_id:el.dataset.id,p_decision:'approved',p_note:null});local.brief=await api.rpc('project_control_weekly_brief',{p_project_id:local.brief.project.id,p_week_start:local.brief.week_start});toast('success',L('تم اعتماد الملخص الأسبوعي','Weekly brief approved'));renderBriefDrawer();}else if(action==='pc-brief-return'){openDialog({title:L('إرجاع الملخص الأسبوعي','Return weekly brief'),subtitle:L('اكتب المطلوب تعديله بوضوح قبل إعادة الإرسال.','Explain clearly what must change before resubmission.'),body:`<form class="form-grid" data-form="pc-brief-return" data-id="${e(el.dataset.id)}"><div class="form-row"><label>${L('ملاحظة المراجع','Reviewer note')}</label><textarea class="textarea" name="note" rows="4" required></textarea></div><button class="btn btn-secondary" type="submit">${icon('reply',14)} ${L('إرجاع للتعديل','Return for changes')}</button></form>`});}return true;}catch(err){formError(err);return true;}}
  async function handleChange(ev){if(ev.target.hasAttribute('data-pc-search')){local.query=ev.target.value||'';render();return true;}return false;}
  function help(){return [L('ابدأ بالمشروعات الحمراء أو الصفراء؛ الدرجة ليست سحرية ويمكنك رؤية كل عامل أثّر فيها.','Start with red or amber projects; the score is not magic and every contributing driver is visible.'),L('افتح المشروع لترى أين يتركز الضغط: موقع، مهمة، مشكلة، عائق، مستند أو معلم.','Open a project to see where pressure is concentrated: site, task, issue, constraint, document, or milestone.'),L('الملخص الأسبوعي يولد الحقائق من التنفيذ الحقيقي؛ الإدارة تضيف الرأي والقرارات والخطة فقط.','The weekly brief generates facts from actual execution; management adds judgement, decisions, and the plan only.'),L('لا تعتمد على النسبة وحدها؛ راقب الفرق عن المتوقع ومصادر التقدم التي كوّنت الرقم.','Do not rely on the percentage alone; watch schedule variance and the sources that produced the progress signal.')];}
  return {page,load,openProject,openWeeklyBrief,reset,handleAction,handleSubmit,handleChange,help,state:local};
}
